type NonErrorStatus = Exclude<AllStatus, "error">;

const currentStatus: NonErrorStatus = "loading";
console.log("Non-error status:", currentStatus);
FULL_CODE_END -->

# `Extract<T, U>`: Intersecting Unions 🎯

The opposite of `Exclude`. It extracts all union members that are assignable to `U`:

```typescript
type TypesA = string | number | (() => void);
type TypesB = number | boolean | (() => void);

// Extracts types present in BOTH unions:
type Common = Extract<TypesA, TypesB>;
// Inferred as number | (() => void)

console.log("Extract demonstrated successfully.");
```

<!-- FULL_CODE_START
type TypesA = string | number | boolean;
type TypesB = number | boolean | object;

type Common = Extract<TypesA, TypesB>;

const numVal: Common = 42;
const boolVal: Common = true;
console.log("Extracted Common values:", numVal, boolVal);
FULL_CODE_END -->

# `NonNullable<T>` 🛡️

Removes `null` and `undefined` from a union type:

```typescript
type ComplexValue = string | number | null | undefined;

type CleanValue = NonNullable<ComplexValue>;
// Inferred as string | number!

const valid: CleanValue = "Guaranteed valid string";
console.log(valid);
```

