# Real-World: Type-Safe CRUD Architecture 🛠️

```typescript
interface ProductEntity {
  id: string;
  sku: string;
  title: string;
  price: number;
  inStock: boolean;
  createdAt: Date;
}

// 1. Create DTO (No ID or createdAt, required fields)
type CreateProductDTO = Omit<ProductEntity, "id" | "createdAt">;

// 2. Update DTO (All fields optional)
type UpdateProductDTO = Partial<CreateProductDTO>;

// 3. Catalog View DTO (Lightweight preview)
type ProductCardDTO = Pick<ProductEntity, "id" | "title" | "price">;

const newProduct: CreateProductDTO = {
  sku: "SKU-9921",
  title: "Ergonomic Desk",
  price: 349.99,
  inStock: true
};

console.log("Create DTO:", newProduct);
```

